<?php
 namespace Pterodactyl\Services\Dezerx\Subdomains; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Cache; use Illuminate\Http\Client\PendingRequest; use Pterodactyl\Services\Dezerx\Settings; class CloudflareClient { private const BASE = 'https://api.cloudflare.com/client/v4'; private const ZONE_TTL = 3600; public function configured(): bool { return $this->token() !== ''; } private function token(): string { return trim((string) (Settings::get(Subdomains::KEY)['cloudflare_token'] ?? '')); } private function http(): PendingRequest { return Http::withToken($this->token()) ->acceptJson() ->asJson() ->timeout(15) ->connectTimeout(5) ->baseUrl(self::BASE); } public function zoneId(string $domain): ?string { if (!$this->configured()) { return null; } $id = Cache::remember('dezerx:cf-zone:' . sha1($domain), self::ZONE_TTL, function () use ($domain) { $response = $this->http()->get('/zones', ['name' => $domain]); $id = $response->json('result.0.id'); return is_string($id) ? $id : null; }); return $id ?: null; } public function records(string $zone, string $type, string $name): array { $result = $this->http() ->get("/zones/{$zone}/dns_records", ['type' => $type, 'name' => $name]) ->json('result'); return is_array($result) ? $result : []; } public function create(string $zone, array $record): array { $response = $this->http()->post("/zones/{$zone}/dns_records", $record); if ($response->successful() && $response->json('success') === true) { return ['ok' => true, 'id' => (string) $response->json('result.id'), 'error' => null]; } return [ 'ok' => false, 'id' => null, 'error' => (string) ($response->json('errors.0.message') ?? 'Cloudflare refused the record.'), ]; } public function delete(string $zone, string $record): bool { return $this->http()->delete("/zones/{$zone}/dns_records/{$record}")->successful(); } public function verify(): array { if (!$this->configured()) { return ['ok' => false, 'message' => 'No API token is set.']; } $response = $this->http()->get('/user/tokens/verify'); return $response->successful() && $response->json('success') === true ? ['ok' => true, 'message' => 'The token is valid.'] : [ 'ok' => false, 'message' => (string) ($response->json('errors.0.message') ?? 'Cloudflare rejected the token.'), ]; } } 